export const getReviewFundingRequestUrl = (id: string,) => {




  return `/api/admin/funding-requests/${id}`
}

/**
 * Disabled by default. Administrative review cannot approve funding while the funding capability is disabled.
 * @summary Review a funding request
 */
export const reviewFundingRequest = async (id: string,
    fundingReview: FundingReview, options?: Parameters<typeof customFetch>[1]): Promise<FundingRequest> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<FundingRequest>(getReviewFundingRequestUrl(id),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(fundingReview)
  }
);}





export const getReviewFundingRequestMutationKey = () => ['reviewFundingRequest'] as const;

