    export type ReviewFundingRequestMutationBody = BodyType<FundingReview>
    export type ReviewFundingRequestMutationError = ErrorType<BadRequestResponse | UnauthorizedResponse | ForbiddenResponse | NotFoundResponse | CapabilityDisabledResponse>
